import React, { useState } from "react";
import axios from "axios";
import Swal from "sweetalert2";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function ParentFeePopup({ onClose }) {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");

  const mainFeeKeys = ["tuition", "development", "computer", "transport", "sports", "artMusic"];

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Enter admission number");
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo}`);
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Record loaded");
      } else toast.error("Not found");
    } catch {
      toast.error("Failed to fetch");
    }
  };

  const payNow = async () => {
    const amt = Number(amount);
    if (!amt) return toast.error("Enter valid amount");
    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "admin-simulated",
      });
      if (res.data.success) {
        toast.success("Payment successful");
        setSummary(null);
        setAdmissionNo("");
        setAmount("");
      } else toast.error("Failed");
    } catch {
      toast.error("Payment failed");
    }
  };

  return (
    <div className="popup-overlay">
      <Toaster />
      <div className="popup-box">
        <button className="popup-close" onClick={onClose}>
          ✖
        </button>
        <h2>💳 Parent Fee Payment</h2>

        <input
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission No"
          style={{ width: "250px", height: "30px" }}
        />
        <button onClick={fetchFee}>Search</button>

        {summary && (
          <div style={{ marginTop: "20px" }}>
            <h4>{summary.student.studentName}</h4>
            <table className="fee-table">
              <thead>
                <tr>
                  <th>Particular</th>
                  <th>Amount</th>
                </tr>
              </thead>
              <tbody>
                {mainFeeKeys.map((key) => (
                  <tr key={key}>
                    <td>{summary.fee.items[key]?.title}</td>
                    <td>₹{summary.fee.items[key]?.amount}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter amount"
            />
            <button onClick={payNow}>Pay Now</button>
          </div>
        )}
      </div>
    </div>
  );
}
